use op_plugin_lint::{audit_source, Severity};
use std::path::PathBuf;

fn fixture(name: &str) -> String {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("tests/fixtures")
        .join(name);
    std::fs::read_to_string(path).expect("fixture readable")
}

#[test]
fn good_plugin_has_no_failures() {
    let report = audit_source("good_plugin.rs", &fixture("good_plugin.rs")).unwrap();
    let fails: Vec<_> = report
        .findings
        .iter()
        .filter(|f| f.severity == Severity::Fail)
        .collect();
    assert!(
        fails.is_empty(),
        "unexpected FAILs on good fixture:\n{}",
        report.to_markdown()
    );
    assert!(report.ok());
}

#[test]
fn bad_plugin_flags_core_contract_gaps() {
    let report = audit_source("bad_plugin.rs", &fixture("bad_plugin.rs")).unwrap();
    assert!(!report.ok());

    let codes: Vec<&str> = report.findings.iter().map(|f| f.code.as_str()).collect();
    // Must catch the high-signal gaps from PLUGIN-RENDER-CONTRACT.md
    for required in [
        "missing_x_oscal_category",
        "missing_field_subid",
        "missing_inventory_submit",
        "deprecated_method_helper",
        "invalid_subid",
    ] {
        assert!(
            codes.contains(&required),
            "expected code `{required}` in findings {codes:?}\n{}",
            report.to_markdown()
        );
    }
}

#[test]
fn bad_plugin_hints_port_range_enhancement() {
    let report = audit_source("bad_plugin.rs", &fixture("bad_plugin.rs")).unwrap();
    let codes: Vec<&str> = report.findings.iter().map(|f| f.code.as_str()).collect();
    assert!(
        codes.contains(&"suggest_port_range"),
        "expected port-range enhancement hint; got {codes:?}"
    );
}

//! Static audit of plugin `.rs` sources against `PLUGIN-RENDER-CONTRACT.md`.
//!
//! No compile step, no `op-plugins` dependency — paste/file input is enough.
//! Reads Rust via `syn`; writes markdown or JSON reports.

mod audit;
mod report;
mod subid;

pub use audit::audit_source;
pub use report::{Finding, Report, Severity};

use serde::Serialize;

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize)]
#[serde(rename_all = "lowercase")]
pub enum Severity {
    Fail,
    Warn,
    Hint,
}

#[derive(Debug, Clone, Serialize)]
pub struct Finding {
    pub severity: Severity,
    pub code: String,
    pub message: String,
    pub location: Option<String>,
}

#[derive(Debug, Clone, Serialize)]
pub struct Report {
    pub source: String,
    pub findings: Vec<Finding>,
}

impl Report {
    pub fn ok(&self) -> bool {
        !self
            .findings
            .iter()
            .any(|f| f.severity == Severity::Fail)
    }

    pub fn fail(
        &mut self,
        code: impl Into<String>,
        message: impl Into<String>,
        location: impl Into<Option<String>>,
    ) {
        self.findings.push(Finding {
            severity: Severity::Fail,
            code: code.into(),
            message: message.into(),
            location: location.into(),
        });
    }

    pub fn warn(
        &mut self,
        code: impl Into<String>,
        message: impl Into<String>,
        location: impl Into<Option<String>>,
    ) {
        self.findings.push(Finding {
            severity: Severity::Warn,
            code: code.into(),
            message: message.into(),
            location: location.into(),
        });
    }

    pub fn hint(
        &mut self,
        code: impl Into<String>,
        message: impl Into<String>,
        location: impl Into<Option<String>>,
    ) {
        self.findings.push(Finding {
            severity: Severity::Hint,
            code: code.into(),
            message: message.into(),
            location: location.into(),
        });
    }

    pub fn to_markdown(&self) -> String {
        let status = if self.ok() { "PASS" } else { "FAIL" };
        let mut out = String::new();
        out.push_str(&format!("# Plugin render-contract audit: {}\n\n", self.source));
        out.push_str(&format!("**Status:** {status}\n\n"));
        if self.findings.is_empty() {
            out.push_str("No findings.\n");
            return out;
        }
        out.push_str("| Severity | Code | Location | Message |\n");
        out.push_str("|---|---|---|---|\n");
        for f in &self.findings {
            let sev = match f.severity {
                Severity::Fail => "FAIL",
                Severity::Warn => "WARN",
                Severity::Hint => "HINT",
            };
            let loc = f.location.as_deref().unwrap_or("—");
            let msg = f.message.replace('|', "\\|").replace('\n', " ");
            out.push_str(&format!(
                "| {sev} | `{}` | `{loc}` | {msg} |\n",
                f.code
            ));
        }
        out.push('\n');
        out
    }

    pub fn to_json(&self) -> anyhow::Result<String> {
        Ok(serde_json::to_string_pretty(self)?)
    }
}

//! Standalone subid taxonomy check (mirrors `op-plugins` oscal helpers).
//! Kept local so this crate builds without the zbus workspace patch.

use regex::Regex;
use std::sync::OnceLock;

const CATEGORIES: &[&str] = &["src", "prj", "sch", "mut", "obs", "evt", "exp"];

const COMPONENT_TYPES: &[&str] = &[
    "this-system",
    "system",
    "interconnection",
    "software",
    "hardware",
    "service",
    "policy",
    "physical",
    "process-procedure",
    "plan",
    "guidance",
    "standard",
    "validation",
    "network",
    // internal
    "agent",
    "container",
    "data",
    "privacy",
    "security",
    "storage",
    // aliases
    "ui",
    "llm",
    "agents",
];

pub fn validate_subid(subid: &str) -> Result<(), String> {
    static RE: OnceLock<Regex> = OnceLock::new();
    let re = RE.get_or_init(|| {
        let segment = r"[a-z0-9]+(?:-[a-z0-9]+)*";
        let pat = format!(
            r"^({})\.({})\.{segment}\.{segment}(?:\.{segment}){{0,2}}(?:@v[1-9][0-9]*)?$",
            CATEGORIES.join("|"),
            COMPONENT_TYPES.join("|"),
        );
        Regex::new(&pat).expect("subid regex")
    });
    if re.is_match(subid) {
        Ok(())
    } else {
        Err(format!("subid does not match required pattern: {subid}"))
    }
}

/// Known `x-*` extension keys the render contract recognizes.
pub const KNOWN_X_KEYS: &[&str] = &[
    "x-oscal-subid",
    "x-oscal-category",
    "x-immutable-paths",
];

//! Syn-based static walk of a plugin `.rs` source against the render contract.

use crate::report::Report;
use crate::subid::{validate_subid, KNOWN_X_KEYS};
use anyhow::{Context, Result};
use syn::{
    parse_file, Attribute, Expr, Fields, Item, ItemStruct, Lit, Meta, MetaNameValue, Visibility,
};

pub fn audit_source(source_name: &str, source: &str) -> Result<Report> {
    let mut report = Report {
        source: source_name.to_string(),
        findings: Vec::new(),
    };

    let file = parse_file(source).context("failed to parse Rust source")?;

    let mut has_inventory = false;
    let mut has_schema_fn = false;
    let mut has_category = false;
    let mut used_deprecated_helper = false;
    let mut used_typed_helper = false;
    let mut has_schema_seeded_test = false;
    let mut has_subid_test = false;
    let mut schemars_structs = 0usize;

    for item in &file.items {
        match item {
            Item::Macro(m) => {
                let path = m.mac.path.segments.iter().map(|s| s.ident.to_string()).collect::<Vec<_>>().join("::");
                if path.ends_with("inventory::submit") || path == "submit" && path_starts_with_inventory(&m.mac.path) {
                    has_inventory = true;
                }
                // inventory::submit! { ... }
                if m.mac.path.is_ident("submit") {
                    // bare submit! uncommon; check attrs/path segments
                }
                if path.contains("inventory") && path.contains("submit") {
                    has_inventory = true;
                }
            }
            Item::Use(u) => {
                let s = quote_path_use(u);
                if s.contains("method_decl_from_schemars_with_output") {
                    used_typed_helper = true;
                }
                if s.contains("method_decl_from_schemars")
                    && !s.contains("method_decl_from_schemars_with_output")
                {
                    used_deprecated_helper = true;
                }
            }
            Item::Fn(f) => {
                let name = f.sig.ident.to_string();
                if name.ends_with("_schema") || name == "schema" {
                    has_schema_fn = true;
                }
                // Walk function body tokens via pretty string for helper calls
                let body = f
                    .block
                    .stmts
                    .iter()
                    .map(|s| quote_stmt(s))
                    .collect::<Vec<_>>()
                    .join("\n");
                if body.contains("method_decl_from_schemars_with_output") {
                    used_typed_helper = true;
                }
                if body.contains("method_decl_from_schemars::<")
                    || body.contains("method_decl_from_schemars(")
                {
                    // only count if not the with_output variant on same call site
                    if !body.contains("method_decl_from_schemars_with_output")
                        || body
                            .lines()
                            .any(|l| {
                                l.contains("method_decl_from_schemars")
                                    && !l.contains("method_decl_from_schemars_with_output")
                            })
                    {
                        used_deprecated_helper = true;
                    }
                }
                for subid in extract_string_lits_matching_subid_shape(&body) {
                    if let Err(e) = validate_subid(&subid) {
                        report.fail(
                            "invalid_subid",
                            e,
                            Some(format!("fn {name}")),
                        );
                    }
                }
            }
            Item::Struct(st) => {
                if has_schemars_derive(&st.attrs) {
                    schemars_structs += 1;
                    audit_struct(&mut report, st, &mut has_category);
                }
            }
            Item::Mod(m) if m.ident == "tests" => {
                if let Some((_, items)) = &m.content {
                    for it in items {
                        if let Item::Fn(tf) = it {
                            let n = tf.sig.ident.to_string();
                            if n.contains("schema_is_schemars") || n.contains("schemars_seeded") {
                                has_schema_seeded_test = true;
                            }
                            if n.contains("subid") {
                                has_subid_test = true;
                            }
                        }
                    }
                }
            }
            _ => {}
        }
    }

    // inventory::submit! appears as Item::Macro with path inventory::submit
    if source.contains("inventory::submit!") {
        has_inventory = true;
    }

    if schemars_structs == 0 {
        report.fail(
            "missing_schemars_struct",
            "no #[derive(schemars::JsonSchema)] structs found — the struct IS the schema",
            None,
        );
    }

    if !has_category {
        report.fail(
            "missing_x_oscal_category",
            "no #[schemars(extend(\"x-oscal-category\" = \"…\"))] on a state struct — declare what the plugin IS",
            None,
        );
    }

    if !has_inventory {
        report.fail(
            "missing_inventory_submit",
            "missing inventory::submit! PluginReg self-registration",
            None,
        );
    }

    if !has_schema_fn {
        report.warn(
            "missing_schema_fn",
            "no `*_schema()` function spotted — expected plugin_schema_from_json wrapper",
            None,
        );
    }

    if used_deprecated_helper {
        report.fail(
            "deprecated_method_helper",
            "uses method_decl_from_schemars (deprecated) — switch to method_decl_from_schemars_with_output with a typed Output",
            None,
        );
    }

    if source.contains("AckOutput") {
        report.warn(
            "ack_output_used",
            "AckOutput is a legacy shortcut — prefer a dedicated typed Output struct for new methods",
            None,
        );
    }

    if used_typed_helper {
        // good signal; no finding
    } else if source.contains("schema.methods") || source.contains("methods.insert") {
        report.warn(
            "untyped_or_missing_method_helper",
            "methods.insert present but method_decl_from_schemars_with_output not found",
            None,
        );
    }

    if !has_schema_seeded_test {
        report.warn(
            "missing_schema_seeded_test",
            "add #[test] fn schema_is_schemars_seeded_and_typed (see antigravity_chat.rs)",
            None,
        );
    }
    if !has_subid_test {
        report.warn(
            "missing_subid_validity_test",
            "add #[test] fn all_subids_are_valid (see antigravity_chat.rs)",
            None,
        );
    }

    // Unknown x-* keys (typo trap: x-oscal-subld)
    for key in extract_x_keys(source) {
        if !KNOWN_X_KEYS.contains(&key.as_str()) && key.starts_with("x-oscal") {
            report.fail(
                "unknown_x_oscal_key",
                format!(
                    "unknown extension key `{key}` — did you mean one of: {}?",
                    KNOWN_X_KEYS.join(", ")
                ),
                None,
            );
        }
    }

    Ok(report)
}

fn audit_struct(report: &mut Report, st: &ItemStruct, has_category: &mut bool) {
    let name = st.ident.to_string();
    let loc = format!("struct {name}");

    let attrs_text = attrs_to_string(&st.attrs);
    if attrs_text.contains("x-oscal-category") {
        *has_category = true;
    }
    if !attrs_text.contains("x-oscal-subid") {
        // Nested helpers often have subids; top-level state should too.
        // Only FAIL for public structs that look like state (name ends with State)
        // or WARN otherwise.
        if name.ends_with("State") {
            report.fail(
                "missing_struct_subid",
                "state struct missing #[schemars(extend(\"x-oscal-subid\" = \"sch.…@v1\"))]",
                Some(loc.clone()),
            );
        } else {
            report.warn(
                "missing_struct_subid",
                "schemars struct missing x-oscal-subid — nested schemas need it for UI audit binding",
                Some(loc.clone()),
            );
        }
    } else {
        for subid in extract_extend_string_values(&st.attrs, "x-oscal-subid") {
            if let Err(e) = validate_subid(&subid) {
                report.fail("invalid_subid", e, Some(loc.clone()));
            }
        }
    }

    if !has_doc_comment(&st.attrs) {
        report.warn(
            "missing_struct_doc",
            "struct has no /// doc comment — renders as blank section description",
            Some(loc.clone()),
        );
    }

    let Fields::Named(fields) = &st.fields else {
        return;
    };

    for field in &fields.named {
        let Some(ident) = &field.ident else { continue };
        let fname = ident.to_string();
        let floc = format!("{name}.{fname}");
        let fattrs = attrs_to_string(&field.attrs);

        if !fattrs.contains("x-oscal-subid") {
            report.fail(
                "missing_field_subid",
                format!("field `{fname}` missing x-oscal-subid"),
                Some(floc.clone()),
            );
        } else {
            for subid in extract_extend_string_values(&field.attrs, "x-oscal-subid") {
                if let Err(e) = validate_subid(&subid) {
                    report.fail("invalid_subid", e, Some(floc.clone()));
                }
            }
        }

        if !has_doc_comment(&field.attrs) {
            report.warn(
                "missing_field_doc",
                format!("field `{fname}` has no /// doc — UI label/tooltip will be empty"),
                Some(floc.clone()),
            );
        }

        let has_serde_default = fattrs.contains("serde(default") || fattrs.contains("serde(default)");
        // syn pretty may normalize differently; also check attribute path
        let serde_default = field.attrs.iter().any(|a| {
            let s = attr_tokens(a);
            s.contains("default") && (s.contains("serde") || a.path().is_ident("serde"))
        });
        if !serde_default && !has_serde_default {
            // Option fields often omit it; still hint
            let ty = type_string(&field.ty);
            if !ty.starts_with("Option") {
                report.hint(
                    "missing_serde_default",
                    format!("consider #[serde(default)] on `{fname}` so defaults round-trip"),
                    Some(floc.clone()),
                );
            }
        }

        // Enhancement: port-like integer without range
        let ty = type_string(&field.ty);
        let looks_port = fname.contains("port") || fname.ends_with("_port");
        let is_int = matches!(
            ty.as_str(),
            "u16" | "u32" | "i32" | "i64" | "u64" | "usize" | "isize"
        );
        if looks_port && is_int && !fattrs.contains("range(") {
            report.hint(
                "suggest_port_range",
                format!(
                    "field `{fname}` looks like a port — add #[schemars(range(min = 1, max = 65535))]"
                ),
                Some(floc.clone()),
            );
        }

        // Enhancement: obs.* fields often should be readOnly
        for subid in extract_extend_string_values(&field.attrs, "x-oscal-subid") {
            if subid.starts_with("obs.") && !fattrs.contains("readOnly") {
                report.hint(
                    "suggest_readonly_obs",
                    format!(
                        "`{fname}` is obs.* — consider #[schemars(extend(\"readOnly\" = true))] if display-only"
                    ),
                    Some(floc.clone()),
                );
            }
        }

        let _ = Visibility::Inherited; // silence; visibility unused
    }
}

fn has_schemars_derive(attrs: &[Attribute]) -> bool {
    attrs.iter().any(|a| {
        if !a.path().is_ident("derive") {
            return false;
        }
        attr_tokens(a).contains("JsonSchema")
    })
}

fn has_doc_comment(attrs: &[Attribute]) -> bool {
    attrs.iter().any(|a| a.path().is_ident("doc"))
}

fn attrs_to_string(attrs: &[Attribute]) -> String {
    attrs.iter().map(attr_tokens).collect::<Vec<_>>().join(" ")
}

fn attr_tokens(attr: &Attribute) -> String {
    attr.to_token_stream_string()
}

trait AttrExt {
    fn to_token_stream_string(&self) -> String;
}

impl AttrExt for Attribute {
    fn to_token_stream_string(&self) -> String {
        // Avoid quote dependency: use Debug-ish via parse tree stringification
        format!("{}", self.meta.to_token_stream_display())
    }
}

trait MetaDisplay {
    fn to_token_stream_display(&self) -> String;
}

impl MetaDisplay for Meta {
    fn to_token_stream_display(&self) -> String {
        match self {
            Meta::Path(p) => p
                .segments
                .iter()
                .map(|s| s.ident.to_string())
                .collect::<Vec<_>>()
                .join("::"),
            Meta::List(l) => {
                let path = l
                    .path
                    .segments
                    .iter()
                    .map(|s| s.ident.to_string())
                    .collect::<Vec<_>>()
                    .join("::");
                format!("{path}({})", l.tokens)
            }
            Meta::NameValue(MetaNameValue { path, value, .. }) => {
                let p = path
                    .segments
                    .iter()
                    .map(|s| s.ident.to_string())
                    .collect::<Vec<_>>()
                    .join("::");
                format!("{p} = {}", expr_string(value))
            }
        }
    }
}

fn expr_string(expr: &Expr) -> String {
    match expr {
        Expr::Lit(l) => match &l.lit {
            Lit::Str(s) => format!("{:?}", s.value()),
            Lit::Int(i) => i.to_string(),
            Lit::Bool(b) => b.value.to_string(),
            _ => format!("{expr:?}"),
        },
        _ => format!("{expr:?}"),
    }
}

fn extract_extend_string_values(attrs: &[Attribute], key: &str) -> Vec<String> {
    let mut out = Vec::new();
    let needle = format!("\"{key}\"");
    for a in attrs {
        let s = attr_tokens(a);
        if !s.contains(&needle) && !s.contains(key) {
            continue;
        }
        // crude: find key = "value" patterns inside extend(...)
        out.extend(pull_assigned_strings(&s, key));
    }
    out
}

fn pull_assigned_strings(s: &str, key: &str) -> Vec<String> {
    let mut out = Vec::new();
    let patterns = [
        format!("\"{key}\" = \""),
        format!("{key}\" = \""),
        format!("\"{key}\"="),
    ];
    for pat in &patterns {
        let mut rest = s;
        while let Some(idx) = rest.find(pat) {
            let after = &rest[idx + pat.len()..];
            // if pattern ended without opening quote for value, skip
            let after = after.strip_prefix('"').unwrap_or(after);
            if let Some(end) = after.find('"') {
                out.push(after[..end].to_string());
                rest = &after[end + 1..];
            } else {
                break;
            }
        }
    }
    out
}

fn extract_x_keys(source: &str) -> Vec<String> {
    let mut keys = Vec::new();
    let mut rest = source;
    while let Some(idx) = rest.find("\"x-") {
        let after = &rest[idx + 1..];
        if let Some(end) = after.find('"') {
            let key = &after[..end];
            if key.starts_with("x-") {
                keys.push(key.to_string());
            }
            rest = &after[end + 1..];
        } else {
            break;
        }
    }
    keys.sort();
    keys.dedup();
    keys
}

fn extract_string_lits_matching_subid_shape(body: &str) -> Vec<String> {
    let mut out = Vec::new();
    let mut rest = body;
    while let Some(idx) = rest.find('"') {
        let after = &rest[idx + 1..];
        if let Some(end) = after.find('"') {
            let lit = &after[..end];
            if lit.contains('.') && (lit.starts_with("src.")
                || lit.starts_with("prj.")
                || lit.starts_with("sch.")
                || lit.starts_with("mut.")
                || lit.starts_with("obs.")
                || lit.starts_with("evt.")
                || lit.starts_with("exp.")
                || lit.contains(".subid")
                || lit.matches('.').count() >= 3)
            {
                // Only validate things that look like subids (category.component...)
                if lit.matches('.').count() >= 3 {
                    out.push(lit.to_string());
                }
            }
            rest = &after[end + 1..];
        } else {
            break;
        }
    }
    out
}

fn type_string(ty: &syn::Type) -> String {
    match ty {
        syn::Type::Path(p) => p
            .path
            .segments
            .last()
            .map(|s| s.ident.to_string())
            .unwrap_or_default(),
        _ => String::new(),
    }
}

fn quote_path_use(u: &syn::ItemUse) -> String {
    format!("{:?}", u.tree)
}

fn quote_stmt(stmt: &syn::Stmt) -> String {
    format!("{stmt:?}")
}

fn path_starts_with_inventory(path: &syn::Path) -> bool {
    path.segments
        .first()
        .is_some_and(|s| s.ident == "inventory")
}

//! CLI for op-plugin-lint.
//!
//! v1: `--input file.rs --output report.md`
//! v2: `--input-dir DIR --output-dir DIR` (batch)

use anyhow::{bail, Context, Result};
use clap::{Parser, ValueEnum};
use op_plugin_lint::audit_source;
use std::fs;
use std::path::{Path, PathBuf};
use std::process::ExitCode;

#[derive(Clone, Copy, ValueEnum)]
enum Format {
    Md,
    Json,
}

#[derive(Parser)]
#[command(
    name = "op-plugin-lint",
    about = "Audit plugin .rs files against PLUGIN-RENDER-CONTRACT.md"
)]
struct Cli {
    /// Single plugin source file (v1).
    #[arg(long, conflicts_with = "input_dir")]
    input: Option<PathBuf>,

    /// Report output file for v1 (markdown or json by --format).
    #[arg(long, conflicts_with = "output_dir")]
    output: Option<PathBuf>,

    /// Directory of plugin .rs files (v2 batch).
    #[arg(long, conflicts_with = "input")]
    input_dir: Option<PathBuf>,

    /// Directory for per-file reports + summary (v2).
    #[arg(long, conflicts_with = "output")]
    output_dir: Option<PathBuf>,

    #[arg(long, value_enum, default_value = "md")]
    format: Format,

    /// Optional path to oscal_subid_registry.rs (reserved for future registry membership checks).
    #[arg(long)]
    registry: Option<PathBuf>,
}

fn main() -> ExitCode {
    match run() {
        Ok(true) => ExitCode::SUCCESS,
        Ok(false) => ExitCode::from(1),
        Err(e) => {
            eprintln!("error: {e:#}");
            ExitCode::from(2)
        }
    }
}

fn run() -> Result<bool> {
    let cli = Cli::parse();
    let _ = cli.registry; // reserved

    match (&cli.input, &cli.output, &cli.input_dir, &cli.output_dir) {
        (Some(input), Some(output), None, None) => {
            let ok = lint_one(input, output, cli.format)?;
            Ok(ok)
        }
        (None, None, Some(input_dir), Some(output_dir)) => {
            lint_dir(input_dir, output_dir, cli.format)
        }
        _ => bail!(
            "use either:\n  --input FILE --output FILE\n  --input-dir DIR --output-dir DIR"
        ),
    }
}

fn lint_one(input: &Path, output: &Path, format: Format) -> Result<bool> {
    let source = fs::read_to_string(input)
        .with_context(|| format!("read {}", input.display()))?;
    let name = input
        .file_name()
        .and_then(|s| s.to_str())
        .unwrap_or("plugin.rs");
    let report = audit_source(name, &source)?;
    write_report(output, &report, format)?;
    eprintln!(
        "{}: {}",
        input.display(),
        if report.ok() { "PASS" } else { "FAIL" }
    );
    Ok(report.ok())
}

fn lint_dir(input_dir: &Path, output_dir: &Path, format: Format) -> Result<bool> {
    fs::create_dir_all(output_dir)
        .with_context(|| format!("create {}", output_dir.display()))?;

    let mut entries: Vec<PathBuf> = fs::read_dir(input_dir)
        .with_context(|| format!("read {}", input_dir.display()))?
        .filter_map(|e| e.ok())
        .map(|e| e.path())
        .filter(|p| p.extension().and_then(|x| x.to_str()) == Some("rs"))
        .filter(|p| {
            let name = p.file_name().and_then(|s| s.to_str()).unwrap_or("");
            // skip module glue / non-plugin files
            !matches!(
                name,
                "mod.rs" | "lib.rs" | "plugin_scaffold_helpers.rs" | "schemars_adapter.rs"
            )
        })
        .collect();
    entries.sort();

    if entries.is_empty() {
        bail!("no .rs plugin files in {}", input_dir.display());
    }

    let mut all_ok = true;
    let mut summary = String::from("# op-plugin-lint batch summary\n\n| File | Status | Fails | Warns | Hints |\n|---|---|---|---|---|\n");

    let ext = match format {
        Format::Md => "md",
        Format::Json => "json",
    };

    for path in &entries {
        let source = fs::read_to_string(path)
            .with_context(|| format!("read {}", path.display()))?;
        let name = path
            .file_name()
            .and_then(|s| s.to_str())
            .unwrap_or("plugin.rs");
        let report = audit_source(name, &source)?;
        let out_path = output_dir.join(format!("{name}.{ext}"));
        write_report(&out_path, &report, format)?;

        let fails = report
            .findings
            .iter()
            .filter(|f| f.severity == op_plugin_lint::Severity::Fail)
            .count();
        let warns = report
            .findings
            .iter()
            .filter(|f| f.severity == op_plugin_lint::Severity::Warn)
            .count();
        let hints = report
            .findings
            .iter()
            .filter(|f| f.severity == op_plugin_lint::Severity::Hint)
            .count();
        let status = if report.ok() { "PASS" } else { "FAIL" };
        if !report.ok() {
            all_ok = false;
        }
        summary.push_str(&format!(
            "| `{name}` | {status} | {fails} | {warns} | {hints} |\n"
        ));
        eprintln!("{name}: {status} (fail={fails} warn={warns} hint={hints})");
    }

    fs::write(output_dir.join("SUMMARY.md"), summary)
        .context("write SUMMARY.md")?;
    Ok(all_ok)
}

fn write_report(path: &Path, report: &op_plugin_lint::Report, format: Format) -> Result<()> {
    if let Some(parent) = path.parent() {
        fs::create_dir_all(parent).ok();
    }
    let body = match format {
        Format::Md => report.to_markdown(),
        Format::Json => report.to_json()?,
    };
    fs::write(path, body).with_context(|| format!("write {}", path.display()))?;
    Ok(())
}

