            if has_schemars_derive(&st.attrs) {
                schemars_structs += 1;
                audit_struct(&mut report, st, &mut has_category);
            }
        }
        Item::Mod(m) if m.ident == "tests" => {
            if let Some((_, items)) = &m.content {
                for it in items {
