    let mut out = Vec::new();
    let patterns = [
        format!("\"{key}\" = \""),
        format!("{key}\" = \""),
        format!("\"{key}\"="),
    ];
    for pat in &patterns {
        let mut rest = s;
        while let Some(idx) = rest.find(pat) {
            let after = &rest[idx + pat.len()..];
            // if pattern ended without opening quote for value, skip
            let after = after.strip_prefix('"').unwrap_or(after);
            if let Some(end) = after.find('"') {
                out.push(after[..end].to_string());
                rest = &after[end + 1..];
            } else {
