//! Static audit of plugin `.rs` sources against `PLUGIN-RENDER-CONTRACT.md`.
//!
//! No compile step, no `op-plugins` dependency by default.
//! Reads Rust via `syn`; optional Inspector-Gadget coverage via `--instance` /
//! `--sealed-schema` (and `--features inspector-gadget` for the live crate).

mod audit;
mod gadget;
mod report;
mod subid;

pub use audit::{audit_source, audit_source_with_coverage, CoverageInputs};
pub use gadget::{
    declared_field_paths, diff_coverage, introspect_json_paths, introspect_json_text,
    paths_from_sealed_schema, CoverageDiff,
};
pub use report::{Finding, Report, Severity};

//! Resolve `--introspect <object/file>` into coverage inputs.
//!
//! | Target | Meaning |
//! |---|---|
//! | path to existing file | JSON file — sealed schema if it has `fields` / `schema.fields`, else instance |
//! | plugin object name (`antigravity`, `antigravity_chat`, …) | fetch sealed schema from ui-model HTTP or local SHM |
//! | `gcloud` | shallow `gcloud --help` group list as a synthetic element set |

use crate::audit::CoverageInputs;
use anyhow::{bail, Context, Result};
use serde_json::{json, Value};
use std::path::Path;
use std::process::Command;

/// Resolve a user-supplied introspect target into JSON the coverage pass can use.
pub fn resolve_introspect_target(target: &str) -> Result<CoverageInputs> {
    let path = Path::new(target);
    if path.is_file() {
        return resolve_file(path);
    }
    match target {
        "gcloud" => resolve_gcloud(),
        name if looks_like_plugin_id(name) => resolve_plugin_object(name),
        other => bail!(
            "unknown --introspect target `{other}`\n\
             use a JSON file path, a plugin id (e.g. antigravity), or `gcloud`"
        ),
    }
}

fn looks_like_plugin_id(name: &str) -> bool {
    !name.is_empty()
        && name
            .chars()
            .all(|c| c.is_ascii_alphanumeric() || c == '_' || c == '-')
        && !name.contains('.')
        && !name.contains('/')
}

fn resolve_file(path: &Path) -> Result<CoverageInputs> {
    let text = std::fs::read_to_string(path)
        .with_context(|| format!("read introspect file {}", path.display()))?;
    let value: Value = serde_json::from_str(&text)
        .with_context(|| format!("parse JSON {}", path.display()))?;

    if value.pointer("/schema/fields").is_some() || value.get("fields").is_some() {
        Ok(CoverageInputs {
            sealed_schema_json: Some(text),
            instance_json: None,
        })
    } else {
        Ok(CoverageInputs {
            instance_json: Some(text),
            sealed_schema_json: None,
        })
    }
}

fn resolve_plugin_object(plugin_id: &str) -> Result<CoverageInputs> {
    // 1) Explicit URL override
    if let Ok(base) = std::env::var("OP_PLUGIN_LINT_SCHEMA_URL") {
        let url = if base.contains("{plugin}") {
            base.replace("{plugin}", plugin_id)
        } else if base.ends_with('/') {
            format!("{base}{plugin_id}")
        } else {
            format!("{base}/{plugin_id}")
        };
        if let Ok(text) = http_get(&url) {
            return Ok(CoverageInputs {
                sealed_schema_json: Some(text),
                instance_json: None,
            });
        }
    }

    // 2) Common op-web ui-model endpoints (router/host)
    let candidates = [
        format!("http://10.0.0.2:8080/api/ui-model/plugin-schema/{plugin_id}"),
        format!("http://127.0.0.1:8080/api/ui-model/plugin-schema/{plugin_id}"),
        format!("http://127.0.0.1:18080/api/ui-model/plugin-schema/{plugin_id}"),
    ];
    for url in &candidates {
        if let Ok(text) = http_get(url) {
            if text.contains("\"fields\"") {
                return Ok(CoverageInputs {
                    sealed_schema_json: Some(text),
                    instance_json: None,
                });
            }
        }
    }

    // 3) Local SHM blob catalog (on host)
    if let Some(text) = read_shm_plugin_schema(plugin_id) {
        return Ok(CoverageInputs {
            sealed_schema_json: Some(text),
            instance_json: None,
        });
    }

    bail!(
        "could not resolve plugin object `{plugin_id}` for --introspect\n\
         tried ui-model HTTP + /dev/shm blob catalog\n\
         fix: pass a file (`--introspect ./schema.json`) or set OP_PLUGIN_LINT_SCHEMA_URL"
    )
}

fn read_shm_plugin_schema(plugin_id: &str) -> Option<String> {
    // Prefer the catalog helper shape if present as a pre-exported JSON dump;
    // otherwise reconstruct a minimal wrapper from a sibling dump path convention.
    let candidates = [
        format!("/dev/shm/opdbus/plugin-schemas/{plugin_id}.json"),
        format!("/tmp/opdbus-plugin-schema-{plugin_id}.json"),
    ];
    for p in candidates {
        if let Ok(text) = std::fs::read_to_string(p) {
            if text.contains("\"fields\"") {
                return Some(text);
            }
        }
    }
    None
}

fn resolve_gcloud() -> Result<CoverageInputs> {
    let output = Command::new("gcloud")
        .args(["--help"])
        .output()
        .context("spawn gcloud --help (is gcloud installed?)")?;
    if !output.status.success() {
        bail!(
            "gcloud --help failed: {}",
            String::from_utf8_lossy(&output.stderr)
        );
    }
    let stdout = String::from_utf8_lossy(&output.stdout);
    let mut groups = Vec::new();
    let mut in_groups = false;
    for line in stdout.lines() {
        let t = line.trim();
        if t == "GROUPS" || t.starts_with("GROUPS ") {
            in_groups = true;
            continue;
        }
        if in_groups {
            if t.is_empty() || t == "COMMANDS" || t.starts_with("COMMANDS ") {
                if t.starts_with("COMMANDS") {
                    break;
                }
                continue;
            }
            // "  compute                    Create and manage ..."
            let name = t.split_whitespace().next().unwrap_or("");
            if !name.is_empty() && name.chars().all(|c| c.is_ascii_lowercase() || c == '-') {
                groups.push(name.to_string());
            }
        }
    }
    // Synthetic instance so gadget path walk sees each group as an element.
    let mut map = serde_json::Map::new();
    for g in &groups {
        map.insert(g.clone(), json!({ "present": true }));
    }
    let instance = Value::Object(map);
    Ok(CoverageInputs {
        instance_json: Some(serde_json::to_string_pretty(&instance)?),
        sealed_schema_json: None,
    })
}

/// Minimal HTTP GET via `curl` (no reqwest dep — keeps crate zbus-free).
fn http_get(url: &str) -> Result<String> {
    let output = Command::new("curl")
        .args(["-fsS", "--max-time", "8", url])
        .output()
        .with_context(|| format!("curl {url}"))?;
    if !output.status.success() {
        bail!("curl failed for {url}");
    }
    Ok(String::from_utf8(output.stdout)?)
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::io::Write;

    #[test]
    fn file_with_fields_is_sealed_schema() {
        let dir = std::env::temp_dir();
        let path = dir.join("op-plugin-lint-sealed-test.json");
        let mut f = std::fs::File::create(&path).unwrap();
        write!(
            f,
            r#"{{"plugin":"demo","schema":{{"fields":{{"status":{{"field_type":"string"}}}}}}}}"#
        )
        .unwrap();
        let cov = resolve_introspect_target(path.to_str().unwrap()).unwrap();
        assert!(cov.sealed_schema_json.is_some());
        assert!(cov.instance_json.is_none());
        let _ = std::fs::remove_file(path);
    }

    #[test]
    fn file_without_fields_is_instance() {
        let dir = std::env::temp_dir();
        let path = dir.join("op-plugin-lint-instance-test.json");
        let mut f = std::fs::File::create(&path).unwrap();
        write!(f, r#"{{"status":"ok","bridge":{{"url":"x"}}}}"#).unwrap();
        let cov = resolve_introspect_target(path.to_str().unwrap()).unwrap();
        assert!(cov.instance_json.is_some());
        assert!(cov.sealed_schema_json.is_none());
        let _ = std::fs::remove_file(path);
    }
}

//! Static audit of plugin `.rs` sources against `PLUGIN-RENDER-CONTRACT.md`.
//!
//! Optional Inspector-Gadget coverage via `--introspect <object/file>`.

mod audit;
mod gadget;
mod introspect;
mod report;
mod subid;

pub use audit::{audit_source, audit_source_with_coverage, CoverageInputs};
pub use gadget::{
    declared_field_paths, diff_coverage, introspect_json_paths, introspect_json_text,
    paths_from_sealed_schema, CoverageDiff,
};
pub use introspect::resolve_introspect_target;
pub use report::{Finding, Report, Severity};

//! CLI for op-plugin-lint.
//!
//! ```text
//! # static only
//! op-plugin-lint --input plugin.rs --output report.md
//!
//! # + Inspector Gadget coverage — file or named object
//! op-plugin-lint --input antigravity.rs --output report.md \
//!   --introspect antigravity
//! op-plugin-lint --input antigravity.rs --output report.md \
//!   --introspect ./antigravity.schema.json
//! ```

use anyhow::{bail, Context, Result};
use clap::{Parser, ValueEnum};
use op_plugin_lint::{
    audit_source, audit_source_with_coverage, resolve_introspect_target, CoverageInputs,
};
use std::fs;
use std::path::{Path, PathBuf};
use std::process::ExitCode;

#[derive(Clone, Copy, ValueEnum)]
enum Format {
    Md,
    Json,
}

#[derive(Parser)]
#[command(
    name = "op-plugin-lint",
    about = "Audit plugin .rs files against PLUGIN-RENDER-CONTRACT.md"
)]
struct Cli {
    /// Single plugin source file (v1).
    #[arg(long, conflicts_with = "input_dir")]
    input: Option<PathBuf>,

    /// Report output file for v1.
    #[arg(long, conflicts_with = "output_dir")]
    output: Option<PathBuf>,

    /// Directory of plugin .rs files (v2 batch).
    #[arg(long, conflicts_with = "input")]
    input_dir: Option<PathBuf>,

    /// Directory for per-file reports + SUMMARY.md (v2).
    #[arg(long, conflicts_with = "output")]
    output_dir: Option<PathBuf>,

    #[arg(long, value_enum, default_value = "md")]
    format: Format,

    /// What to introspect for element coverage: a JSON file path, a plugin
    /// object id (`antigravity`), or `gcloud`.
    /// Alias: `--intospec` (typo-tolerant).
    #[arg(long = "introspect", visible_alias = "intospec")]
    introspect: Option<String>,

    /// Optional path to oscal_subid_registry.rs (reserved).
    #[arg(long)]
    registry: Option<PathBuf>,
}

fn main() -> ExitCode {
    match run() {
        Ok(true) => ExitCode::SUCCESS,
        Ok(false) => ExitCode::from(1),
        Err(e) => {
            eprintln!("error: {e:#}");
            ExitCode::from(2)
        }
    }
}

fn run() -> Result<bool> {
    let cli = Cli::parse();
    let _ = cli.registry;

    let coverage = match &cli.introspect {
        Some(target) => {
            eprintln!("introspect: {target}");
            resolve_introspect_target(target)?
        }
        None => CoverageInputs::default(),
    };

    match (&cli.input, &cli.output, &cli.input_dir, &cli.output_dir) {
        (Some(input), Some(output), None, None) => {
            lint_one(input, output, cli.format, &coverage)
        }
        (None, None, Some(input_dir), Some(output_dir)) => {
            lint_dir(input_dir, output_dir, cli.format, &coverage)
        }
        _ => bail!(
            "use either:\n  --input FILE --output FILE [--introspect OBJECT|FILE]\n  --input-dir DIR --output-dir DIR [--introspect OBJECT|FILE]"
        ),
    }
}

fn lint_one(
    input: &Path,
    output: &Path,
    format: Format,
    coverage: &CoverageInputs,
) -> Result<bool> {
    let source =
        fs::read_to_string(input).with_context(|| format!("read {}", input.display()))?;
    let name = input
        .file_name()
        .and_then(|s| s.to_str())
        .unwrap_or("plugin.rs");
    let report = if coverage.instance_json.is_some() || coverage.sealed_schema_json.is_some() {
        audit_source_with_coverage(name, &source, coverage)?
    } else {
        audit_source(name, &source)?
    };
    write_report(output, &report, format)?;
    eprintln!(
        "{}: {}",
        input.display(),
        if report.ok() { "PASS" } else { "FAIL" }
    );
    Ok(report.ok())
}

fn lint_dir(
    input_dir: &Path,
    output_dir: &Path,
    format: Format,
    coverage: &CoverageInputs,
) -> Result<bool> {
    fs::create_dir_all(output_dir)
        .with_context(|| format!("create {}", output_dir.display()))?;

    let mut entries: Vec<PathBuf> = fs::read_dir(input_dir)
        .with_context(|| format!("read {}", input_dir.display()))?
        .filter_map(|e| e.ok())
        .map(|e| e.path())
        .filter(|p| p.extension().and_then(|x| x.to_str()) == Some("rs"))
        .filter(|p| {
            let name = p.file_name().and_then(|s| s.to_str()).unwrap_or("");
            !matches!(
                name,
                "mod.rs" | "lib.rs" | "plugin_scaffold_helpers.rs" | "schemars_adapter.rs"
            )
        })
        .collect();
    entries.sort();

    if entries.is_empty() {
        bail!("no .rs plugin files in {}", input_dir.display());
    }

    let mut all_ok = true;
    let mut summary = String::from(
        "# op-plugin-lint batch summary\n\n| File | Status | Fails | Warns | Hints |\n|---|---|---|---|---|\n",
    );
    let ext = match format {
        Format::Md => "md",
        Format::Json => "json",
    };

    for path in &entries {
        let source =
            fs::read_to_string(path).with_context(|| format!("read {}", path.display()))?;
        let name = path
            .file_name()
            .and_then(|s| s.to_str())
            .unwrap_or("plugin.rs");
        // For batch + named object introspect, only apply coverage when the
        // file basename matches the object (antigravity.rs ↔ antigravity).
        let use_cov = coverage_applies_to_file(name, coverage);
        let report = if use_cov {
            audit_source_with_coverage(name, &source, coverage)?
        } else {
            audit_source(name, &source)?
        };
        let out_path = output_dir.join(format!("{name}.{ext}"));
        write_report(&out_path, &report, format)?;

        let fails = report
            .findings
            .iter()
            .filter(|f| f.severity == op_plugin_lint::Severity::Fail)
            .count();
        let warns = report
            .findings
            .iter()
            .filter(|f| f.severity == op_plugin_lint::Severity::Warn)
            .count();
        let hints = report
            .findings
            .iter()
            .filter(|f| f.severity == op_plugin_lint::Severity::Hint)
            .count();
        let status = if report.ok() { "PASS" } else { "FAIL" };
        if !report.ok() {
            all_ok = false;
        }
        summary.push_str(&format!(
            "| `{name}` | {status} | {fails} | {warns} | {hints} |\n"
        ));
        eprintln!("{name}: {status} (fail={fails} warn={warns} hint={hints})");
    }

    fs::write(output_dir.join("SUMMARY.md"), summary).context("write SUMMARY.md")?;
    Ok(all_ok)
}

fn coverage_applies_to_file(filename: &str, coverage: &CoverageInputs) -> bool {
    if coverage.instance_json.is_none() && coverage.sealed_schema_json.is_none() {
        return false;
    }
    // File-based introspect applies to every file in the batch.
    // Object-fetched sealed schema: only when JSON names the plugin matching the file.
    if let Some(sealed) = &coverage.sealed_schema_json {
        if let Ok(v) = serde_json::from_str::<serde_json::Value>(sealed) {
            if let Some(plugin) = v.get("plugin").and_then(|p| p.as_str()) {
                let stem = filename.trim_end_matches(".rs");
                return stem == plugin || stem.replace('-', "_") == plugin.replace('-', "_");
            }
        }
    }
    true
}

fn write_report(path: &Path, report: &op_plugin_lint::Report, format: Format) -> Result<()> {
    if let Some(parent) = path.parent() {
        fs::create_dir_all(parent).ok();
    }
    let body = match format {
        Format::Md => report.to_markdown(),
        Format::Json => report.to_json()?,
    };
    fs::write(path, body).with_context(|| format!("write {}", path.display()))?;
    Ok(())
}

