/// Resolve a user-supplied introspect target into JSON the coverage pass can use.
pub fn resolve_introspect_target(target: &str) -> Result<CoverageInputs> {
    resolve_introspect_target_for_plugin(target, None)
}

/// Like [`resolve_introspect_target`], and when `plugin_rs` is set, auto-load
/// sibling `common/*.rs` type sources for `#[serde(flatten)]` resolution.
pub fn resolve_introspect_target_for_plugin(
    target: &str,
    plugin_rs: Option<&Path>,
) -> Result<CoverageInputs> {
    let mut cov = {
        let path = Path::new(target);
        if path.is_file() {
            resolve_file(path)?
        } else {
            match target {
                "gcloud" => resolve_gcloud()?,
                name if looks_like_plugin_id(name) => resolve_plugin_object(name)?,
                other => bail!(
                    "unknown --introspect target `{other}`\n\
                     use a JSON file path, a plugin id (e.g. antigravity), or `gcloud`"
                ),
            }
        }
    };
    if let Some(plugin) = plugin_rs {
        cov.extra_rust_sources = discover_type_sources(plugin);
    }
    Ok(cov)
}

fn discover_type_sources(plugin_rs: &Path) -> Vec<String> {
    let mut out = Vec::new();
    let Some(dir) = plugin_rs.parent() else {
        return out;
    };
    // state_plugins/common/*.rs — shared projection types used via flatten.
    let common = dir.join("common");
    if common.is_dir() {
        if let Ok(rd) = std::fs::read_dir(&common) {
            let mut paths: Vec<_> = rd
                .filter_map(|e| e.ok())
                .map(|e| e.path())
                .filter(|p| p.extension().and_then(|x| x.to_str()) == Some("rs"))
                .filter(|p| {
                    p.file_name()
                        .and_then(|s| s.to_str())
                        .is_some_and(|n| n != "mod.rs")
                })
                .collect();
            paths.sort();
            for p in paths {
                if let Ok(text) = std::fs::read_to_string(&p) {
                    out.push(text);
                }
            }
        }
    }
    out
}

