//! External CLI binary introspection via recursive `--help` walks.
//!
//! This is the *real* Inspector Gadget direction: discover flags/commands from
//! an upstream binary (e.g. `/fast/zeroclaw/bin/zeroclaw`), never from a schema
//! we already authored.
//!
//! Tuned for clap-style help (`Commands:` / `Arguments:` / `Options:`), which
//! ZeroClaw 0.8.x emits.

use anyhow::{bail, Context, Result};
use regex::Regex;
use serde::Serialize;
use serde_json::{json, Value};
use std::collections::{BTreeSet, HashSet};
use std::path::{Path, PathBuf};
use std::process::Command;
use std::sync::OnceLock;

#[derive(Debug, Clone, Serialize)]
pub struct CliFlag {
    pub name: String,
    pub short: Option<String>,
    pub value_name: Option<String>,
    pub description: String,
}

#[derive(Debug, Clone, Serialize)]
pub struct CliNode {
    /// Full argv path after the binary, e.g. `["models", "list"]`.
    pub path: Vec<String>,
    pub usage: String,
    pub about: String,
    pub commands: Vec<String>,
    pub flags: Vec<CliFlag>,
    pub arguments: Vec<String>,
}

#[derive(Debug, Clone, Serialize)]
pub struct BinarySurface {
    pub binary: String,
    pub version: Option<String>,
    pub nodes: Vec<CliNode>,
    /// Flattened element paths for coverage diffs, e.g.
    /// `cmd.models`, `cmd.models.list`, `flag.models.list.--model-provider`.
    pub element_paths: Vec<String>,
}

/// Walk `binary --help` recursively up to `max_depth` subcommand levels.
pub fn introspect_binary(binary: &Path, max_depth: usize) -> Result<BinarySurface> {
    if !binary.exists() {
        bail!("binary not found: {}", binary.display());
    }
    let version = run_version(binary);
    let mut nodes = Vec::new();
    let mut visited = HashSet::new();
    walk(binary, &[], max_depth, &mut nodes, &mut visited)?;

    let mut element_paths = BTreeSet::new();
    for node in &nodes {
        if node.path.is_empty() {
            element_paths.insert("cmd".to_string());
        } else {
            element_paths.insert(format!("cmd.{}", node.path.join(".")));
        }
        for c in &node.commands {
            let mut p = node.path.clone();
            p.push(c.clone());
            element_paths.insert(format!("cmd.{}", p.join(".")));
        }
        for f in &node.flags {
            let scope = if node.path.is_empty() {
                "root".to_string()
            } else {
                node.path.join(".")
            };
            let fname = f.name.trim_start_matches('-').replace('-', "_");
            element_paths.insert(format!("flag.{scope}.{}", fname));
        }
        for a in &node.arguments {
            let scope = if node.path.is_empty() {
                "root".to_string()
            } else {
                node.path.join(".")
            };
            element_paths.insert(format!("arg.{scope}.{}", a.replace('-', "_")));
        }
    }

    Ok(BinarySurface {
        binary: binary.display().to_string(),
        version,
        nodes,
        element_paths: element_paths.into_iter().collect(),
    })
}

/// Coverage-friendly JSON instance: each element path → `{ "present": true }`.
pub fn surface_as_instance_json(surface: &BinarySurface) -> Result<String> {
    let mut map = serde_json::Map::new();
    for path in &surface.element_paths {
        map.insert(path.clone(), json!({ "present": true }));
    }
    // Also embed the full surface under `_surface` for the report consumer.
    map.insert(
        "_surface".to_string(),
        serde_json::to_value(surface).context("serialize BinarySurface")?,
    );
    Ok(serde_json::to_string_pretty(&Value::Object(map))?)
}

fn walk(
    binary: &Path,
    path: &[String],
    depth_left: usize,
    out: &mut Vec<CliNode>,
    visited: &mut HashSet<Vec<String>>,
) -> Result<()> {
    if !visited.insert(path.to_vec()) {
        return Ok(());
    }
    let help = run_help(binary, path)?;
    let node = parse_clap_help(path, &help);
    let children = node.commands.clone();
    out.push(node);

    if depth_left == 0 {
        return Ok(());
    }
    for child in children {
        if child == "help" || child == "completions" {
            continue;
        }
        let mut next = path.to_vec();
        next.push(child);
        walk(binary, &next, depth_left - 1, out, visited)?;
    }
    Ok(())
}

fn run_help(binary: &Path, path: &[String]) -> Result<String> {
    let mut cmd = Command::new(binary);
    for p in path {
        cmd.arg(p);
    }
    cmd.arg("--help");
    let output = cmd
        .output()
        .with_context(|| format!("spawn {} {:?} --help", binary.display(), path))?;
    // clap often prints help to stdout; some tools use stderr.
    let mut text = String::from_utf8_lossy(&output.stdout).to_string();
    text.push_str(&String::from_utf8_lossy(&output.stderr));
    if text.trim().is_empty() {
        bail!(
            "empty help from {} {:?} (status={})",
            binary.display(),
            path,
            output.status
        );
    }
    Ok(text)
}

fn run_version(binary: &Path) -> Option<String> {
    let output = Command::new(binary).arg("--version").output().ok()?;
    let text = String::from_utf8_lossy(&output.stdout);
    text.lines().next().map(|s| s.trim().to_string())
}

fn parse_clap_help(path: &[String], help: &str) -> CliNode {
    let about = help
        .lines()
        .map(str::trim)
        .find(|l| !l.is_empty() && !l.starts_with("Usage:"))
        .unwrap_or("")
        .to_string();

    let usage = help
        .lines()
        .find(|l| l.trim_start().starts_with("Usage:"))
        .map(|l| l.trim().to_string())
        .unwrap_or_default();

    let commands = section_names(help, &["Commands:"]);
    let arguments = section_names(help, &["Arguments:", "Args:"]);
    let flags = parse_options(help);

    CliNode {
        path: path.to_vec(),
        usage,
        about,
        commands,
        flags,
        arguments,
    }
}

fn section_names(help: &str, headers: &[&str]) -> Vec<String> {
    let mut names = Vec::new();
    let mut in_section = false;
    let name_re = cmd_name_re();

    for line in help.lines() {
        let trimmed = line.trim();
        if headers.iter().any(|h| trimmed == *h) {
            in_section = true;
            continue;
        }
        if in_section {
            if trimmed.is_empty() {
                continue;
            }
            // Next ALL-CAPS-ish section header (Options:, Global Options:, …)
            if !line.starts_with(' ') && !line.starts_with('\t') && trimmed.ends_with(':') {
                break;
            }
            if let Some(caps) = name_re.captures(line) {
                let name = caps.get(1).unwrap().as_str();
                if name != "help" {
                    names.push(name.to_string());
                }
            }
        }
    }
    names
}

fn parse_options(help: &str) -> Vec<CliFlag> {
    let mut flags = Vec::new();
    let mut in_section = false;
    let mut current: Option<CliFlag> = None;
    let flag_re = flag_re();

    for line in help.lines() {
        let trimmed = line.trim();
        if trimmed == "Options:" || trimmed == "Global Options:" {
            in_section = true;
            continue;
        }
        if in_section {
            if !line.starts_with(' ')
                && !line.starts_with('\t')
                && !trimmed.is_empty()
                && trimmed.ends_with(':')
                && !trimmed.starts_with('-')
            {
                if let Some(f) = current.take() {
                    flags.push(f);
                }
                break;
            }
            if let Some(caps) = flag_re.captures(line) {
                if let Some(f) = current.take() {
                    flags.push(f);
                }
                let long = caps.name("long").map(|m| m.as_str().to_string());
                let short = caps.name("short").map(|m| m.as_str().to_string());
                let value_name = caps.name("val").map(|m| m.as_str().to_string());
                let name = long
                    .clone()
                    .or_else(|| short.clone())
                    .unwrap_or_else(|| trimmed.to_string());
                // remainder of line after match may hold description
                let desc = caps
                    .name("desc")
                    .map(|m| m.as_str().trim().to_string())
                    .unwrap_or_default();
                current = Some(CliFlag {
                    name,
                    short,
                    value_name,
                    description: desc,
                });
            } else if let Some(ref mut f) = current {
                if !trimmed.is_empty() {
                    if !f.description.is_empty() {
                        f.description.push(' ');
                    }
                    f.description.push_str(trimmed);
                }
            }
        }
    }
    if let Some(f) = current {
        flags.push(f);
    }
    flags
}

fn cmd_name_re() -> &'static Regex {
    static RE: OnceLock<Regex> = OnceLock::new();
    RE.get_or_init(|| Regex::new(r"^\s{2,8}([a-zA-Z][\w-]*)\s{2,}").unwrap())
}

fn flag_re() -> &'static Regex {
    static RE: OnceLock<Regex> = OnceLock::new();
    //  -h, --help                  Print help
    //      --config-dir <CONFIG_DIR>
    //  -v, --verbose
    RE.get_or_init(|| {
        Regex::new(
            r"(?x)
            ^\s*
            (?:(?P<short>-[a-zA-Z0-9]),\s*)?
            (?:(?P<long>--[\w-]+))?
            (?:\s+(?P<val><[^>]+>|[\w-]+))?
            \s{2,}(?P<desc>.*)$
            |^\s*(?P<long2>--[\w-]+)(?:\s+(?P<val2><[^>]+>))?\s*$
            ",
        )
        .unwrap()
    })
}

/// Resolve a user target that names a binary (path, or `binary:PATH`).
pub fn resolve_binary_target(target: &str) -> Option<PathBuf> {
    let path = if let Some(rest) = target.strip_prefix("binary:") {
        PathBuf::from(rest)
    } else {
        PathBuf::from(target)
    };
    if path.is_file() {
        // Heuristic: treat as binary if executable bit set OR no .json/.rs suffix.
        let name = path.file_name().and_then(|s| s.to_str()).unwrap_or("");
        if name.ends_with(".json") || name.ends_with(".rs") || name.ends_with(".md") {
            return None;
        }
        return Some(path);
    }
    None
}

#[cfg(test)]
mod tests {
    use super::*;

    const SAMPLE: &str = r#"Manage provider model catalogs

Usage: zeroclaw models [OPTIONS] <COMMAND>

Commands:
  refresh  Refresh and cache provider models
  list     List cached models for a provider
  set      Set the default model in config
  status   Show current model configuration and cache status
  help     Print this message or the help of the given subcommand(s)

Options:
      --config-dir <CONFIG_DIR>
      --log-level <LOG_LEVEL>    Lowest severity recorded
  -v, --verbose                  Surface recorded logs
  -h, --help                     Print help
"#;

    #[test]
    fn parses_clap_commands_and_flags() {
        let node = parse_clap_help(&["models".into()], SAMPLE);
        assert!(node.commands.contains(&"refresh".into()));
        assert!(node.commands.contains(&"list".into()));
        assert!(!node.commands.contains(&"help".into()));
        let names: Vec<_> = node.flags.iter().map(|f| f.name.as_str()).collect();
        assert!(
            names.iter().any(|n| n.contains("verbose") || *n == "-v" || *n == "--verbose"),
            "flags={names:?}"
        );
        assert!(names.iter().any(|n| n.contains("config-dir") || n.contains("config_dir") || *n == "--config-dir"),
            "flags={names:?}");
    }
}

