//! Static audit of plugin `.rs` sources against `PLUGIN-RENDER-CONTRACT.md`.
//!
//! External discovery via `--introspect <binary|file>` (CLI help-walk).

mod audit;
mod binary;
mod gadget;
mod introspect;
mod report;
mod subid;

pub use audit::{audit_source, audit_source_with_coverage, CoverageInputs};
pub use binary::{
    introspect_binary, surface_as_instance_json, surface_to_json, BinaryIntrospectOpts,
    BinarySurface,
};
pub use gadget::{
    declared_field_paths, declared_field_paths_multi, diff_coverage, introspect_json_paths,
    introspect_json_text, paths_from_sealed_schema, CoverageDiff,
};
pub use introspect::{
    resolve_introspect_target, resolve_introspect_target_for_plugin,
    resolve_introspect_target_with, IntrospectOpts,
};
pub use report::{Finding, Report, Severity};

//! CLI for op-plugin-lint.
//!
//! Discover an upstream CLI surface (ZeroClaw example):
//! ```text
//! op-plugin-lint \
//!   --introspect /fast/zeroclaw/bin/zeroclaw \
//!   --ssh root@192.168.1.1 \
//!   --introspect-depth 2 \
//!   --surface-out /tmp/zeroclaw.surface.json \
//!   --input crates/op-plugins/src/state_plugins/zeroclaw.rs \
//!   --output /tmp/zeroclaw.lint.md
//! ```

use anyhow::{bail, Context, Result};
use clap::{Parser, ValueEnum};
use op_plugin_lint::{
    audit_source, audit_source_with_coverage, resolve_introspect_target_with, CoverageInputs,
    IntrospectOpts,
};
use std::fs;
use std::path::{Path, PathBuf};
use std::process::ExitCode;

#[derive(Clone, Copy, ValueEnum)]
enum Format {
    Md,
    Json,
}

#[derive(Parser)]
#[command(
    name = "op-plugin-lint",
    about = "Audit plugin .rs files against PLUGIN-RENDER-CONTRACT.md; introspect external CLIs"
)]
struct Cli {
    #[arg(long, conflicts_with = "input_dir")]
    input: Option<PathBuf>,

    #[arg(long, conflicts_with = "output_dir")]
    output: Option<PathBuf>,

    #[arg(long, conflicts_with = "input")]
    input_dir: Option<PathBuf>,

    #[arg(long, conflicts_with = "output")]
    output_dir: Option<PathBuf>,

    #[arg(long, value_enum, default_value = "md")]
    format: Format,

    /// External target to discover: binary path, `binary:PATH`, JSON dump, or (drift-only) plugin id.
    /// Alias: `--intospec`.
    #[arg(long = "introspect", visible_alias = "intospec")]
    introspect: Option<String>,

    /// SSH host for remote binary help-walk (e.g. root@192.168.1.1).
    #[arg(long)]
    ssh: Option<String>,

    /// Max subcommand depth for binary --help walks (default 2).
    #[arg(long, default_value_t = 2)]
    introspect_depth: usize,

    /// Write the raw BinarySurface JSON (commands/flags tree) here.
    #[arg(long)]
    surface_out: Option<PathBuf>,

    #[arg(long)]
    registry: Option<PathBuf>,
}

fn main() -> ExitCode {
    match run() {
        Ok(true) => ExitCode::SUCCESS,
        Ok(false) => ExitCode::from(1),
        Err(e) => {
            eprintln!("error: {e:#}");
            ExitCode::from(2)
        }
    }
}

fn run() -> Result<bool> {
    let cli = Cli::parse();
    let _ = cli.registry;

    let iopts = IntrospectOpts {
        max_depth: cli.introspect_depth,
        ssh: cli.ssh.clone(),
    };

    // Surface-only mode: introspect binary, write surface, optional report.
    if cli.input.is_none() && cli.input_dir.is_none() {
        let Some(target) = &cli.introspect else {
            bail!(
                "need --input/--input-dir, or --introspect with --surface-out\n\
                 example:\n  --introspect /fast/zeroclaw/bin/zeroclaw --ssh root@192.168.1.1 --surface-out /tmp/zc.json"
            );
        };
        let cov = resolve_introspect_target_with(target, None, &iopts)?;
        let Some(surface) = &cov.binary_surface_json else {
            bail!("--introspect did not produce a binary surface (is the target a CLI binary?)");
        };
        let out = cli
            .surface_out
            .as_ref()
            .or(cli.output.as_ref())
            .context("pass --surface-out or --output for surface-only introspect")?;
        fs::write(out, surface).with_context(|| format!("write {}", out.display()))?;
        eprintln!("wrote surface {}", out.display());
        return Ok(true);
    }

    let coverage = match &cli.introspect {
        Some(target) => {
            let plugin_hint = cli.input.as_deref();
            let cov = resolve_introspect_target_with(target, plugin_hint, &iopts)?;
            if let (Some(path), Some(surface)) = (&cli.surface_out, &cov.binary_surface_json) {
                fs::write(path, surface).with_context(|| format!("write {}", path.display()))?;
                eprintln!("wrote surface {}", path.display());
            }
            cov
        }
        None => CoverageInputs::default(),
    };

    match (&cli.input, &cli.output, &cli.input_dir, &cli.output_dir) {
        (Some(input), Some(output), None, None) => lint_one(input, output, cli.format, &coverage),
        (None, None, Some(input_dir), Some(output_dir)) => {
            lint_dir(input_dir, output_dir, cli.format, &coverage)
        }
        _ => bail!("use --input/--output or --input-dir/--output-dir"),
    }
}

fn lint_one(
    input: &Path,
    output: &Path,
    format: Format,
    coverage: &CoverageInputs,
) -> Result<bool> {
    let source =
        fs::read_to_string(input).with_context(|| format!("read {}", input.display()))?;
    let name = input
        .file_name()
        .and_then(|s| s.to_str())
        .unwrap_or("plugin.rs");
    let report = if coverage.instance_json.is_some() || coverage.sealed_schema_json.is_some() {
        audit_source_with_coverage(name, &source, coverage)?
    } else {
        audit_source(name, &source)?
    };
    write_report(output, &report, format)?;
    eprintln!(
        "{}: {}",
        input.display(),
        if report.ok() { "PASS" } else { "FAIL" }
    );
    Ok(report.ok())
}

fn lint_dir(
    input_dir: &Path,
    output_dir: &Path,
    format: Format,
    coverage: &CoverageInputs,
) -> Result<bool> {
    fs::create_dir_all(output_dir)
        .with_context(|| format!("create {}", output_dir.display()))?;

    let mut entries: Vec<PathBuf> = fs::read_dir(input_dir)
        .with_context(|| format!("read {}", input_dir.display()))?
        .filter_map(|e| e.ok())
        .map(|e| e.path())
        .filter(|p| p.extension().and_then(|x| x.to_str()) == Some("rs"))
        .filter(|p| {
            let name = p.file_name().and_then(|s| s.to_str()).unwrap_or("");
            !matches!(
                name,
                "mod.rs" | "lib.rs" | "plugin_scaffold_helpers.rs" | "schemars_adapter.rs"
            )
        })
        .collect();
    entries.sort();
    if entries.is_empty() {
        bail!("no .rs plugin files in {}", input_dir.display());
    }

    let mut all_ok = true;
    let mut summary = String::from(
        "# op-plugin-lint batch summary\n\n| File | Status | Fails | Warns | Hints |\n|---|---|---|---|---|\n",
    );
    let ext = match format {
        Format::Md => "md",
        Format::Json => "json",
    };

    for path in &entries {
        let source =
            fs::read_to_string(path).with_context(|| format!("read {}", path.display()))?;
        let name = path
            .file_name()
            .and_then(|s| s.to_str())
            .unwrap_or("plugin.rs");
        let report = audit_source_with_coverage(name, &source, coverage)?;
        let out_path = output_dir.join(format!("{name}.{ext}"));
        write_report(&out_path, &report, format)?;
        let fails = report
            .findings
            .iter()
            .filter(|f| f.severity == op_plugin_lint::Severity::Fail)
            .count();
        let warns = report
            .findings
            .iter()
            .filter(|f| f.severity == op_plugin_lint::Severity::Warn)
            .count();
        let hints = report
            .findings
            .iter()
            .filter(|f| f.severity == op_plugin_lint::Severity::Hint)
            .count();
        let status = if report.ok() { "PASS" } else { "FAIL" };
        if !report.ok() {
            all_ok = false;
        }
        summary.push_str(&format!(
            "| `{name}` | {status} | {fails} | {warns} | {hints} |\n"
        ));
        eprintln!("{name}: {status}");
    }
    fs::write(output_dir.join("SUMMARY.md"), summary)?;
    Ok(all_ok)
}

fn write_report(path: &Path, report: &op_plugin_lint::Report, format: Format) -> Result<()> {
    if let Some(parent) = path.parent() {
        fs::create_dir_all(parent).ok();
    }
    let body = match format {
        Format::Md => report.to_markdown(),
        Format::Json => report.to_json()?,
    };
    fs::write(path, body).with_context(|| format!("write {}", path.display()))?;
    Ok(())
}

