//! Dump the full ZeroClaw PluginSchema (state fields + typed methods).
//!
//! ```bash
//! cargo run -p op-plugins --example dump_zeroclaw_schema -- /tmp/zeroclaw.full.schema.json
//! ```

use std::env;
use std::fs;
use std::path::PathBuf;
use std::process::ExitCode;

fn main() -> ExitCode {
    let out = env::args()
        .nth(1)
        .map(PathBuf::from)
        .unwrap_or_else(|| PathBuf::from("/tmp/zeroclaw.full.schema.json"));

    let schema = op_plugins::state_plugins::zeroclaw::zeroclaw_plugin_schema();
    let json = match serde_json::to_string_pretty(&schema) {
        Ok(j) => j,
        Err(e) => {
            eprintln!("serialize schema: {e}");
            return ExitCode::from(1);
        }
    };

    if let Err(e) = fs::write(&out, format!("{json}\n")) {
        eprintln!("write {}: {e}", out.display());
        return ExitCode::from(1);
    }

    eprintln!(
        "wrote {} (fields={} methods={})",
        out.display(),
        schema.fields.len(),
        schema.methods.len()
    );
    ExitCode::SUCCESS
}

//! Gap analysis: introspected surface paths not represented in the plugin.

use serde::Serialize;
use serde_json::Value;
use std::collections::{BTreeMap, BTreeSet};

#[derive(Debug, Clone, Serialize)]
pub struct IntrospectGaps {
    pub surface_paths_total: usize,
    pub signal_paths_considered: usize,
    pub covered_approx: usize,
    pub missing_from_plugin: usize,
    pub missing_cli_commands: Vec<String>,
    pub missing_config_fields: Vec<String>,
    pub missing_by_group: BTreeMap<String, usize>,
    /// Full missing paths (capped for report size; see surface-out for catalog).
    pub missing_paths_sample: Vec<String>,
    pub note: String,
}

pub fn gaps_from_surface_json(
    surface_json: &str,
    plugin_field_leaves: &BTreeSet<String>,
    plugin_methods: &BTreeSet<String>,
) -> Option<IntrospectGaps> {
    let surface: Value = serde_json::from_str(surface_json).ok()?;
    let paths = surface
        .get("element_paths")
        .and_then(|v| v.as_array())
        .cloned()
        .unwrap_or_default();

    let plugin_text_leaves: BTreeSet<String> = plugin_field_leaves
        .iter()
        .map(|s| s.to_ascii_lowercase())
        .collect();
    let method_snakes: BTreeSet<String> = plugin_methods
        .iter()
        .flat_map(|m| {
            let lower = m.to_ascii_lowercase();
            let snake = camel_to_snake(m);
            [lower, snake]
        })
        .collect();

    let mut covered = 0usize;
    let mut missing = Vec::new();
    let mut by_group: BTreeMap<String, usize> = BTreeMap::new();

    for p in &paths {
        let Some(path) = p.as_str() else { continue };
        if is_noise(path) || !is_signal(path) {
            continue;
        }
        if surface_covered(path, &plugin_text_leaves, &method_snakes) {
            covered += 1;
        } else {
            *by_group.entry(group_of(path)).or_default() += 1;
            missing.push(path.to_string());
        }
    }

    let missing_cli: Vec<String> = missing
        .iter()
        .filter(|p| {
            p.contains("Commands.") || p.contains(".Commands.")
        })
        .cloned()
        .collect();
    let missing_config: Vec<String> = missing
        .iter()
        .filter(|p| p.contains("zeroclaw_config") || p.contains(".config."))
        .cloned()
        .collect();

    const SAMPLE_CAP: usize = 500;
    let sample = if missing.len() > SAMPLE_CAP {
        missing[..SAMPLE_CAP].to_vec()
    } else {
        missing.clone()
    };

    Some(IntrospectGaps {
        surface_paths_total: paths.len(),
        signal_paths_considered: covered + missing.len(),
        covered_approx: covered,
        missing_from_plugin: missing.len(),
        missing_cli_commands: missing_cli,
        missing_config_fields: missing_config,
        missing_by_group: by_group,
        missing_paths_sample: sample,
        note: "Introspected findings not represented in the plugin .rs — this is the gap list. Full catalog is --surface-out.".into(),
    })
}

fn camel_to_snake(s: &str) -> String {
    let mut out = String::new();
    for (i, c) in s.chars().enumerate() {
        if c.is_uppercase() {
            if i > 0 {
                out.push('_');
            }
            out.extend(c.to_lowercase());
        } else {
            out.push(c);
        }
    }
    out
}

fn is_noise(p: &str) -> bool {
    let pl = p.to_ascii_lowercase();
    [
        "aardvark",
        "robot_kit",
        "firmware",
        "/tests.",
        ".tests.",
        "cargo.",
        "deny.",
        "clippy",
        "github.workflows",
        "docker-compose",
        "locales",
        "bench",
    ]
    .iter()
    .any(|n| pl.contains(n))
}

fn is_signal(p: &str) -> bool {
    p.starts_with("struct.zeroclaw")
        || p.starts_with("enum.zeroclaw")
        || p.starts_with("struct.zeroclaw_")
        || p.starts_with("toml.")
        || p.starts_with("proto.")
        || p.contains("zeroclaw_config")
        || p.contains("Commands.")
}

fn group_of(p: &str) -> String {
    if p.contains("Commands.") || p.contains(".Commands.") {
        "cli_commands".into()
    } else if p.contains("zeroclaw_config") {
        "zeroclaw_config".into()
    } else if p.starts_with("toml.") {
        "toml".into()
    } else if p.starts_with("enum.") {
        "rust_enum".into()
    } else if p.starts_with("struct.") {
        "rust_struct".into()
    } else {
        "other".into()
    }
}

fn surface_covered(
    path: &str,
    plugin_leaves: &BTreeSet<String>,
    method_snakes: &BTreeSet<String>,
) -> bool {
    let leaf = path.rsplit('.').next().unwrap_or(path);
    let leaf_l = leaf.to_ascii_lowercase();
    let snake = camel_to_snake(leaf);
    if plugin_leaves.contains(&leaf_l) || plugin_leaves.contains(&snake) {
        return true;
    }
    if method_snakes.contains(&leaf_l) || method_snakes.contains(&snake) {
        return true;
    }
    // ModelsCommands.List ↔ list_models
    let parts: Vec<&str> = path.split('.').collect();
    if parts.len() >= 2 {
        let variant = parts[parts.len() - 1].to_ascii_lowercase();
        let parent = parts[parts.len() - 2]
            .to_ascii_lowercase()
            .replace("commands", "")
            .replace("command", "");
        let g1 = format!("{variant}_{parent}").trim_matches('_').to_string();
        let g2 = format!("{parent}_{variant}").trim_matches('_').to_string();
        if method_snakes.contains(&g1) || method_snakes.contains(&g2) {
            return true;
        }
    }
    false
}

//! Emit a full contract-shaped plugin document from a plugin `.rs` source,
//! optionally including introspect gap findings.

use crate::audit::{audit_source_with_coverage, CoverageInputs};
use crate::gaps::{gaps_from_surface_json, IntrospectGaps};
use crate::gadget::declared_field_paths_multi;
use crate::report::Report;
use anyhow::{Context, Result};
use regex::Regex;
use serde::Serialize;
use serde_json::{json, Value};
use std::collections::{BTreeMap, BTreeSet};
use syn::{parse_file, Attribute, Fields, Item, Lit, Meta, Type};

#[derive(Debug, Clone, Serialize)]
pub struct CompletePluginDocument {
    pub contract: &'static str,
    pub source: String,
    pub plugin: PluginEmit,
    pub audit: AuditEmit,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub introspect: Option<IntrospectEmit>,
}

#[derive(Debug, Clone, Serialize)]
pub struct PluginEmit {
    pub name: String,
    pub category: String,
    pub version: String,
    pub description: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub display_name: Option<String>,
    pub state_root: Option<String>,
    pub fields: BTreeMap<String, FieldEmit>,
    pub nested_types: BTreeMap<String, BTreeMap<String, FieldEmit>>,
    pub methods: BTreeMap<String, MethodEmit>,
}

#[derive(Debug, Clone, Serialize)]
pub struct FieldEmit {
    pub rust_type: String,
    pub description: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub subid: Option<String>,
    pub has_serde_default: bool,
    pub optional: bool,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub json_type: Option<&'static str>,
}

#[derive(Debug, Clone, Serialize)]
pub struct MethodEmit {
    pub name: String,
    pub input_type: String,
    pub output_type: String,
    pub side_effect: String,
    pub idempotent: bool,
    pub required_capability: String,
    pub subid: String,
    pub args: Value,
    pub returns: Value,
}

#[derive(Debug, Clone, Serialize)]
pub struct AuditEmit {
    pub ok: bool,
    pub fail: usize,
    pub warn: usize,
    pub hint: usize,
    pub findings: Value,
}

#[derive(Debug, Clone, Serialize)]
pub struct IntrospectEmit {
    pub surface_kind: Option<String>,
    pub surface_source: Option<String>,
    pub files_by_kind: Option<Value>,
    pub by_kind: Option<Value>,
    pub element_path_count: usize,
    pub gaps: IntrospectGaps,
}

pub fn emit_complete_plugin(
    source_name: &str,
    source: &str,
    coverage: &CoverageInputs,
    extra_sources: &[&str],
) -> Result<CompletePluginDocument> {
    let mut sources = vec![source];
    sources.extend_from_slice(extra_sources);

    let report = audit_source_with_coverage(source_name, source, coverage)?;
    let file = parse_file(source).context("parse plugin source for emit")?;

    let consts = extract_plugin_consts(source);
    let structs = collect_structs(&file);
    let methods = extract_methods(source, &structs);

    let state_root = structs
        .keys()
        .find(|k| k.ends_with("State"))
        .cloned()
        .or_else(|| structs.keys().next().cloned());

    let mut fields = BTreeMap::new();
    if let Some(root) = &state_root {
        if let Some(fs) = structs.get(root) {
            fields = fs.clone();
        }
    }

    let mut nested = BTreeMap::new();
    for (name, fs) in &structs {
        if Some(name) == state_root.as_ref() {
            continue;
        }
        // Keep Input/Output and nested schema types used by state/methods.
        nested.insert(name.clone(), fs.clone());
    }

    let declared = declared_field_paths_multi(&sources).unwrap_or_default();
    let field_leaves: BTreeSet<String> = declared
        .iter()
        .map(|p| p.rsplit('.').next().unwrap_or(p).to_ascii_lowercase())
        .collect();
    let method_names: BTreeSet<String> = methods.keys().cloned().collect();

    let introspect = coverage.binary_surface_json.as_ref().map(|surface| {
        let v: Value = serde_json::from_str(surface).unwrap_or(json!({}));
        let gaps = gaps_from_surface_json(surface, &field_leaves, &method_names).unwrap_or(
            IntrospectGaps {
                surface_paths_total: 0,
                signal_paths_considered: 0,
                covered_approx: 0,
                missing_from_plugin: 0,
                missing_cli_commands: vec![],
                missing_config_fields: vec![],
                missing_by_group: BTreeMap::new(),
                missing_paths_sample: vec![],
                note: "failed to compute gaps".into(),
            },
        );
        IntrospectEmit {
            surface_kind: v
                .get("kind")
                .and_then(|x| x.as_str())
                .map(|s| s.to_string()),
            surface_source: v
                .get("binary")
                .and_then(|x| x.as_str())
                .map(|s| s.to_string()),
            files_by_kind: v.get("files_by_kind").cloned(),
            by_kind: v.get("by_kind").cloned(),
            element_path_count: v
                .get("element_paths")
                .and_then(|a| a.as_array())
                .map(|a| a.len())
                .unwrap_or(0),
            gaps,
        }
    });

    Ok(CompletePluginDocument {
        contract: "PLUGIN-RENDER-CONTRACT.md",
        source: source_name.to_string(),
        plugin: PluginEmit {
            name: consts
                .get("PLUGIN_NAME")
                .cloned()
                .unwrap_or_else(|| source_name.trim_end_matches(".rs").to_string()),
            category: consts
                .get("PLUGIN_CATEGORY")
                .cloned()
                .unwrap_or_else(|| "software".into()),
            version: consts
                .get("PLUGIN_VERSION")
                .cloned()
                .unwrap_or_else(|| "0.0.0".into()),
            description: consts
                .get("PLUGIN_DESCRIPTION")
                .cloned()
                .unwrap_or_default(),
            display_name: consts.get("PLUGIN_DISPLAY_NAME").cloned(),
            state_root,
            fields,
            nested_types: nested,
            methods,
        },
        audit: audit_emit(&report),
        introspect,
    })
}

pub fn complete_to_json(doc: &CompletePluginDocument) -> Result<String> {
    Ok(serde_json::to_string_pretty(doc)?)
}

pub fn complete_to_markdown(doc: &CompletePluginDocument) -> String {
    let mut out = String::new();
    out.push_str(&format!(
        "# Complete plugin: {}\n\n",
        doc.plugin.name
    ));
    out.push_str(&format!("**Contract:** {}\n\n", doc.contract));
    out.push_str(&format!("**Source:** `{}`\n\n", doc.source));
    out.push_str(&format!(
        "**Identity:** {} {} ({}) — {}\n\n",
        doc.plugin.name,
        doc.plugin.version,
        doc.plugin.category,
        doc.plugin.description
    ));
    if let Some(root) = &doc.plugin.state_root {
        out.push_str(&format!("**State root:** `{root}`\n\n"));
    }

    out.push_str("## Fields\n\n");
    out.push_str("| Field | Rust type | Subid | Doc |\n|---|---|---|---|\n");
    for (name, f) in &doc.plugin.fields {
        out.push_str(&format!(
            "| `{name}` | `{}` | {} | {} |\n",
            f.rust_type,
            f.subid.as_deref().unwrap_or("—"),
            escape_md(&f.description)
        ));
    }

    out.push_str("\n## Methods (typed)\n\n");
    for (name, m) in &doc.plugin.methods {
        out.push_str(&format!(
            "### `{name}`\n\n- side_effect: `{}`\n- idempotent: {}\n- capability: `{}`\n- subid: `{}`\n- input: `{}` → output: `{}`\n\n",
            m.side_effect, m.idempotent, m.required_capability, m.subid, m.input_type, m.output_type
        ));
        out.push_str("**args**\n\n```json\n");
        out.push_str(&serde_json::to_string_pretty(&m.args).unwrap_or_else(|_| "{}".into()));
        out.push_str("\n```\n\n**returns**\n\n```json\n");
        out.push_str(&serde_json::to_string_pretty(&m.returns).unwrap_or_else(|_| "{}".into()));
        out.push_str("\n```\n\n");
    }

    out.push_str("## Audit\n\n");
    out.push_str(&format!(
        "Status: {} (fail={} warn={} hint={})\n\n",
        if doc.audit.ok { "PASS" } else { "FAIL" },
        doc.audit.fail,
        doc.audit.warn,
        doc.audit.hint
    ));

    if let Some(intro) = &doc.introspect {
        out.push_str("## Introspect findings (gaps vs plugin)\n\n");
        out.push_str(&format!(
            "- surface: {} ({})\n- element_paths: {}\n- missing_from_plugin: **{}**\n- missing_cli_commands: **{}**\n- missing_config_fields: **{}**\n\n",
            intro.surface_source.as_deref().unwrap_or("?"),
            intro.surface_kind.as_deref().unwrap_or("?"),
            intro.element_path_count,
            intro.gaps.missing_from_plugin,
            intro.gaps.missing_cli_commands.len(),
            intro.gaps.missing_config_fields.len(),
        ));
        out.push_str(&format!("{}\n\n", intro.gaps.note));
        out.push_str("### CLI commands not in plugin\n\n");
        for p in intro.gaps.missing_cli_commands.iter().take(120) {
            out.push_str(&format!("- `{p}`\n"));
        }
        if intro.gaps.missing_cli_commands.len() > 120 {
            out.push_str(&format!(
                "- … +{} more\n",
                intro.gaps.missing_cli_commands.len() - 120
            ));
        }
        out.push_str("\n### Config / struct fields not in plugin (sample)\n\n");
        for p in intro.gaps.missing_config_fields.iter().take(80) {
            out.push_str(&format!("- `{p}`\n"));
        }
    }

    out
}

fn escape_md(s: &str) -> String {
    s.replace('|', "\\|").replace('\n', " ")
}

fn audit_emit(report: &Report) -> AuditEmit {
    let fail = report
        .findings
        .iter()
        .filter(|f| matches!(f.severity, crate::report::Severity::Fail))
        .count();
    let warn = report
        .findings
        .iter()
        .filter(|f| matches!(f.severity, crate::report::Severity::Warn))
        .count();
    let hint = report
        .findings
        .iter()
        .filter(|f| matches!(f.severity, crate::report::Severity::Hint))
        .count();
    let findings = serde_json::to_value(&report.findings).unwrap_or(json!([]));
    AuditEmit {
        ok: report.ok(),
        fail,
        warn,
        hint,
        findings,
    }
}

fn extract_plugin_consts(source: &str) -> BTreeMap<String, String> {
    let re = Regex::new(
        r#"const\s+(PLUGIN_(?:NAME|CATEGORY|VERSION|DESCRIPTION|DISPLAY_NAME))\s*:\s*&str\s*=\s*"([^"]*)""#,
    )
    .expect("regex");
    let mut out = BTreeMap::new();
    for cap in re.captures_iter(source) {
        out.insert(cap[1].to_string(), cap[2].to_string());
    }
    out
}

fn collect_structs(file: &syn::File) -> BTreeMap<String, BTreeMap<String, FieldEmit>> {
    let mut out = BTreeMap::new();
    for item in &file.items {
        let Item::Struct(st) = item else { continue };
        if !has_jsonschema(&st.attrs) {
            continue;
        }
        let Fields::Named(fields) = &st.fields else {
            continue;
        };
        let mut map = BTreeMap::new();
        for f in &fields.named {
            let Some(ident) = &f.ident else { continue };
            let ty = type_string(&f.ty);
            let optional = ty.starts_with("Option<");
            map.insert(
                ident.to_string(),
                FieldEmit {
                    rust_type: ty.clone(),
                    description: doc_comment(&f.attrs),
                    subid: schemars_subid(&f.attrs),
                    has_serde_default: has_serde_default(&f.attrs),
                    optional,
                    json_type: rust_to_json_type(&ty),
                },
            );
        }
        out.insert(st.ident.to_string(), map);
    }
    out
}

fn extract_methods(
    source: &str,
    structs: &BTreeMap<String, BTreeMap<String, FieldEmit>>,
) -> BTreeMap<String, MethodEmit> {
    // method_decl_from_schemars_with_output::<In, Out>(
    //     "Name",
    //     SideEffect::Read|Mutation,
    //     true|false,
    //     "cap...",
    //     "subid...",
    // )
    let re = Regex::new(
        r#"(?s)method_decl_from_schemars_with_output\s*::\s*<\s*([A-Za-z0-9_]+)\s*,\s*([A-Za-z0-9_]+)\s*>\s*\(\s*"([^"]+)"\s*,\s*[^:]+::(Read|Mutation)\s*,\s*(true|false)\s*,\s*"([^"]*)"\s*,\s*"([^"]*)""#,
    )
    .expect("regex");

    let mut out = BTreeMap::new();
    for cap in re.captures_iter(source) {
        let input_ty = cap[1].to_string();
        let output_ty = cap[2].to_string();
        let name = cap[3].to_string();
        let side = cap[4].to_ascii_lowercase();
        let idempotent = &cap[5] == "true";
        let capab = cap[6].to_string();
        let subid = cap[7].to_string();
        let args = struct_to_json_schema(&input_ty, structs);
        let returns = struct_to_json_schema(&output_ty, structs);
        out.insert(
            name.clone(),
            MethodEmit {
                name,
                input_type: input_ty,
                output_type: output_ty,
                side_effect: side,
                idempotent,
                required_capability: capab,
                subid,
                args,
                returns,
            },
        );
    }
    out
}

fn struct_to_json_schema(
    type_name: &str,
    structs: &BTreeMap<String, BTreeMap<String, FieldEmit>>,
) -> Value {
    let Some(fields) = structs.get(type_name) else {
        return json!({
            "title": type_name,
            "type": "object",
            "description": format!("type `{type_name}` not found in this .rs (may live in common/)"),
            "properties": {}
        });
    };
    let mut properties = serde_json::Map::new();
    let mut required = Vec::new();
    for (name, f) in fields {
        let mut prop = serde_json::Map::new();
        if let Some(jt) = f.json_type {
            prop.insert("type".into(), json!(jt));
        } else {
            prop.insert("type".into(), json!("object"));
            prop.insert("x-rust-type".into(), json!(f.rust_type));
        }
        if !f.description.is_empty() {
            prop.insert("description".into(), json!(f.description));
        }
        if let Some(sub) = &f.subid {
            prop.insert("x-oscal-subid".into(), json!(sub));
        }
        properties.insert(name.clone(), Value::Object(prop));
        if !f.optional && !f.has_serde_default {
            required.push(name.clone());
        }
    }
    let mut obj = serde_json::Map::new();
    obj.insert("title".into(), json!(type_name));
    obj.insert("type".into(), json!("object"));
    obj.insert("properties".into(), Value::Object(properties));
    if !required.is_empty() {
        obj.insert("required".into(), json!(required));
    }
    Value::Object(obj)
}

fn has_jsonschema(attrs: &[Attribute]) -> bool {
    attrs.iter().any(|a| {
        a.path().is_ident("derive") && format!("{}", quote_meta(a)).contains("JsonSchema")
    })
}

fn quote_meta(a: &Attribute) -> String {
    format!("{}", a.meta.to_token_stream_display())
}

trait ToTokensDisplay {
    fn to_token_stream_display(&self) -> String;
}

impl ToTokensDisplay for Meta {
    fn to_token_stream_display(&self) -> String {
        quote::ToTokens::to_token_stream(self).to_string()
    }
}

