pub fn parse_clap_help(path: &[String], help: &str) -> CliNode {
    let about = help
        .lines()
        .map(str::trim)
        .find(|l| !l.is_empty() && !l.starts_with("Usage:"))
        .unwrap_or("")
        .to_string();

    let usage = help
        .lines()
        .find(|l| l.trim_start().starts_with("Usage:"))
        .map(|l| l.trim().to_string())
        .unwrap_or_default();

    let commands = section_names(help, &["Commands:"]);
    let arguments = section_names(help, &["Arguments:", "Args:"]);
    let flags = parse_options(help);

    CliNode {
        path: path.to_vec(),
        usage,
        about,
        commands,
        flags,
        arguments,
    }
}

fn section_names(help: &str, headers: &[&str]) -> Vec<String> {
    let mut names = Vec::new();
    let mut in_section = false;
    let name_re = cmd_name_re();

    for line in help.lines() {
        let trimmed = line.trim();
        if headers.iter().any(|h| trimmed == *h) {
            in_section = true;
            continue;
        }
        if in_section {
            if trimmed.is_empty() {
                continue;
            }
            if !line.starts_with(' ') && !line.starts_with('\t') && trimmed.ends_with(':') {
                break;
            }
            if let Some(caps) = name_re.captures(line) {
                let name = caps.get(1).unwrap().as_str();
                if name != "help" {
                    names.push(name.to_string());
                }
            }
        }
    }
    names
}

fn parse_options(help: &str) -> Vec<CliFlag> {
    let mut flags = Vec::new();
    let mut in_section = false;
    let mut current: Option<CliFlag> = None;

    for line in help.lines() {
        let trimmed = line.trim();
        if trimmed == "Options:" || trimmed == "Global Options:" {
            in_section = true;
            continue;
        }
        if !in_section {
            continue;
        }
        if !line.starts_with(' ')
            && !line.starts_with('\t')
            && !trimmed.is_empty()
            && trimmed.ends_with(':')
            && !trimmed.starts_with('-')
        {
            if let Some(f) = current.take() {
                flags.push(f);
            }
            break;
