            if !trimmed.is_empty() {
                if !f.description.is_empty() {
                    f.description.push(' ');
                }
                f.description.push_str(trimmed);
            }
        }
    }
    if let Some(f) = current {
        flags.push(f);
    }
    flags
}

fn parse_flag_line(line: &str) -> Option<CliFlag> {
    let trimmed = line.trim_start();
    if !trimmed.starts_with('-') {
        return None;
