# Pull schema to local via wget through router, then build a naive form-spec from fields to show what renderer would get
ssh -o ConnectTimeout=6 -o BatchMode=yes root@192.168.1.1 'wget -qO- http://10.0.0.2:8080/api/ui-model/plugin-schema/antigravity_chat' > /tmp/ag_chat_schema.live.json
python3 <<'PY'
import json
from pathlib import Path
d=json.load(open('/tmp/ag_chat_schema.live.json'))
s=d['schema']

def field_to_widget(name, f, path=""):
    """Naive schema→json-render mapping like a thin renderer would do."""
    ft=f.get('field_type')
    desc=f.get('description') or ''
    full=f"{path}.{name}" if path else name
    if isinstance(ft, str):
        if ft in ('string','integer','number','boolean'):
            return {"type":"Input" if ft!='boolean' else 'Checkbox', "props":{"name":full,"label":name,"description":desc,"valueType":ft}}
        return {"type":"Text", "props":{"text":f"{name}: {ft}"}}
    if isinstance(ft, dict):
        if 'object' in ft:
            children=[]
            for k,v in ft['object'].items():
                children.append(field_to_widget(k,v,full))
            return {"type":"Card","props":{"title":name,"description":desc},"children":children}
        if 'array' in ft:
            item=ft['array']
            return {"type":"Table","props":{"title":name,"description":desc,"item":field_to_widget('item', item if isinstance(item,dict) else {'field_type':item}, full)}}
        if 'map' in ft:
            return {"type":"KeyValue","props":{"title":name}}
    return {"type":"Unknown","props":{"name":name,"ft":str(ft)[:80]}}

# Build "chat UI" attempt from schema alone
root_children=[]
for name,f in s.get('fields',{}).items():
    if name in ('actor_id','capability_id'): continue
    root_children.append(field_to_widget(name,f))

methods=[]
for mname,m in s.get('methods',{}).items():
    methods.append({
        "type":"Button",
        "props":{"label":mname,"side_effect":m.get('side_effect'),"has_typed_args": bool(m.get('args',{}).get('properties'))}
    })

spec={
  "type":"Page",
  "props":{"title":"Antigravity Chat (schema-driven render)"},
  "children":[
    {"type":"Stack","props":{"gap":16},"children":root_children},
    {"type":"Stack","props":{"direction":"row","gap":8},"children":methods},
